    """Fill the single-cell horizontal gaps between same-row markers with 2."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] != 0 and row[c + 2] != 0 and row[c + 1] == 0:
                out[r][c + 1] = 2
